"""Invariant probability, backward contraction and qualified symplectic ellipses."""
from ch05_data import add,copied,proposition,D,NS
add('EulerInvariant','5.6',207,[76],r'''This means that with the single exception $\rho(q,p;0)=\delta[q]\delta[p]$ there is no limiting (invariant) distribution for Forward Euler. To put it another way, the only solution, in the weak sense, of $\mathcal L_{\widetilde f}^*\rho=0$ is the point distribution $\delta[q]\delta[p]$, and this solution is not “asymptotically stable.”''',proposition('eulerInvariant_statement'),extra=['[EXTRA]真实Forward Euler映射的不变概率测度，h≠0；一般modified微分方程的弱稳态并非自动等同离散不变测度，原记号作为解释而非未经证明的算子识别。'],missing='待外扩映射不变概率唯一性的紧球测度递推与连续性桥接；不建设一般算子/输运理论。')
add('BackwardEuler','5.6',207,[],r'''As an alternative, consider the Backward Euler method: $q_{n+1}=q_n+hp_{n+1}$, $p_{n+1}=p_n-hq_{n+1}$. Then it is easily shown that both eigenvalues of the matrix lie in the interior of the unit disk, and hence all solutions of the recurrence relation tend to the origin with increasing $n$ (the origin is an attractive equilibrium point).''',copied(D,'backwardEuler'),kind='definition',extra=['[EXTRA]解出的实际二维线性更新，分母1+h²恒正；收缩需h≠0，h=0恒等映射不收缩。'])
add('BackwardEnergyDecay','5.6',207,[],r'''both eigenvalues of the matrix lie in the interior of the unit disk, and hence all solutions of the recurrence relation tend to the origin with increasing $n$.''',f'''theorem backwardEnergyDecay : ∀ (h : ℝ) (z : {NS}E 2) (k : ℕ),
  ((({NS}backwardEuler h)^[k] z) 0)^2+((({NS}backwardEuler h)^[k] z) 1)^2=
    (1+h^2)⁻¹^k*((z 0)^2+(z 1)^2) := by
  sorry''',extra=['[EXTRA]真实有限步平方范数代数恒等式另列；全轨道趋原点及测度弱极限另保留。'],missing='待具体逆Euler更新平方展开和迭代归纳短证明。')
add('BackwardEulerLimit','5.6',207,[77],r'''all solutions of the recurrence relation tend to the origin with increasing $n$ (the origin is an attractive equilibrium point). In this case, all densities evolve toward the Dirac distribution centered at the origin: $\delta[q]\delta[p]$. The only (distributional) solution of $\mathcal L_{\widetilde f}^*\rho=0$ is again $\delta[q]\delta[p]$, which in this case is attractive.''',proposition('backwardEulerLimit_statement'),extra=['[EXTRA]h≠0及实际任意初始概率测度；全轨道收缩与对每个有界连续测试函数的弱趋Dirac两个结论，非普通密度逐点收敛。'],missing='待线性收缩的范数极限及概率测度支配收敛短桥；不建设一般分布/PDE理论。')
add('SymplecticEuler','5.6',207,[],r'''Now consider the application of the Symplectic Euler method, $q_{n+1}=q_n+hp_{n+1}$, $p_{n+1}=p_n-hq_n$.''',copied(D,'symplecticEuler'),kind='definition')
add('SymplecticEulerShadow','5.6',207,[78],r'''the solution through any given initial point remains confined to an ellipse for all $n$ defined by $\widetilde H_h(q,p)=\widetilde H_h(q_0,p_0)$, where $\widetilde H_h$ is the perturbed Hamiltonian defined by the backward error analysis.''',copied('MolecularDynamics/Chapter05/ReviewProofs.lean','symplecticEulerShadow_proved','symplecticEulerShadow'),prior=['MolecularDynamics.Chapter05Review.symplecticEulerShadow_proved'],extra=['[EXTRA]完整实际二次修正能量的一步保持恒等式；正定椭圆资格及所有n保持另条，不以一步式称全部椭圆结论已证。'])
add('SymplecticEulerEllipse','5.6',207,[78],r'''the solution through any given initial point remains confined to an ellipse for all $n$ defined by $\widetilde H_h(q,p)=\widetilde H_h(q_0,p_0)$.''',f'''theorem symplecticEulerEllipse : ∀ h : ℝ,|h| < 2 →
  (∀ z : {NS}E 2,z ≠ 0 → 0 < {NS}shadowOscillator h z) ∧
  (∀ c : ℝ,IsCompact {{z : {NS}E 2 | {NS}shadowOscillator h z ≤ c}}) ∧
  (∀ z : {NS}E 2,∀ k : ℕ,{NS}shadowOscillator h (({NS}symplecticEuler h)^[k] z)=
    {NS}shadowOscillator h z) := by
  sorry''',extra=['[EXTRA]稳定条件|h|<2；原不加资格的椭圆说法在|h|≥2失败。本条保留正定/紧性和所有迭代保持；0能量是退化点。'],prior=['MolecularDynamics.Chapter05Review.symplecticEulerShadow_proved'],missing='待具体二次型正定界、有限维紧性和归纳短桥；不建设大理论。')
add('SymplecticEulerDensity','5.6',207,[79],r'''This implies that a density which is a function of $\widetilde H_h$ will remain invariant under the associated Liouville equation. There are many solutions of $\mathcal L_{\widetilde f}^*\rho=0$, none of which is attractive.''',proposition('symplecticEulerDensity_statement'),extra=['[EXTRA]真实离散映射MeasurePreserving、不变二次能量、实际概率密度r∘Htilde；完整弱Liouville稳态及非吸引另条，所有r都可归一不能自动推出。'],prior=['MolecularDynamics.Chapter05Review.symplecticEulerShadow_proved'],missing='待线性映射单位Jacobian与真实withDensity变换短桥；不建设一般输运理论。')
